identifiers.choose_device:
def choose_device(name="auto"):
    if name != "auto":
        return torch.device(name)
    if torch.cuda.is_available():
        return torch.device("cuda")
    if torch.backends.mps.is_available():
        return torch.device("mps")
    return torch.device("cpu")

identifiers.seed_everything:
def seed_everything(seed):
    random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

identifiers.load_checkpoint:
def load_checkpoint(path, device="cpu", restore_rng=False):
    payload = torch.load(path, map_location="cpu", weights_only=True)
    if payload.get("format_version") not in (1, "quantized-v1", "multimodal-v1"):
        raise ValueError("不支援的 checkpoint 格式")
    model = TinyLM(ModelConfig(**payload["config"]))
    if payload["format_version"] == "multimodal-v1":
        c = payload["modal_config"]
        model = MultiModalLM(model, c["vision_width"], c["audio_width"])
        model.vision = VisionEncoder(c["vision_width"], c["image_size"], c["patch_size"])
        model.audio = AudioEncoder(c["bands"], c["audio_width"])
    if payload["format_version"] == "quantized-v1":
        from tiny_perceptron.quantization import replace_linear_layers

        if restore_rng:
            raise ValueError("量化 checkpoint 是參考推論格式，不能 resume 訓練")
        replace_linear_layers(model, payload["bits"])
    model.load_state_dict(payload["model"], strict=True)
    model.to(device)
    if "trainable_parameters" in payload:
        names = set(payload["trainable_parameters"])
        for name, parameter in model.named_parameters():
            parameter.requires_grad_(name in names)
    if restore_rng:
        restore_checkpoint_rng(payload)
    return model, payload

identifiers.main:
def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--list", action="store_true")
    parser.add_argument("--asset", action="append", help="可重複指定；--asset all 取全部")
    parser.add_argument("--output", type=Path, default=ROOT / "data/training")
    args = parser.parse_args()
    manifest = json.loads((ROOT / "assets/training/manifest.json").read_text(encoding="utf-8"))
    assets = {asset["id"]: asset for asset in manifest["assets"]}
    if args.list or not args.asset:
        for asset in assets.values():
            print(
                json.dumps(
                    {key: asset[key] for key in ("id", "training_records", "archive_bytes", "license")},
                    ensure_ascii=False,
                )
            )
        return
    selected = list(assets) if args.asset == ["all"] else list(dict.fromkeys(args.asset))
    if any(name not in assets for name in selected):
        parser.error("未知的 asset；先用 --list 查看，不會自動下載其他資料")
    for name in selected:
        asset = assets[name]
        archive = ROOT / asset["archive"]
        with archive.open("rb") as source:
            pointer = source.read(128).startswith(b"version https://git-lfs.github.com/spec/v1\n")
        if pointer:
            subprocess.run(
                ["git", "lfs", "pull", "origin", "--include", asset["archive"], "--exclude", ""], cwd=ROOT, check=True
            )
        print(json.dumps(unpack_asset(archive, asset, args.output), ensure_ascii=False))
